:root{--bg:#080d12;--panel:#0e151d;--panel2:#121c26;--line:#20303e;--ink:#eaf2f8;--dim:#8ba0b2;--accent:#5ee7b7;--accent2:#7fb7ff;--warn:#ffb86b;--neg:#ff7d8a;--radius:14px}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:radial-gradient(1100px 520px at 78% -8%,#163043 0%,transparent 65%),var(--bg);color:var(--ink);font-family:Inter,ui-sans-serif,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;font-size:14px;line-height:1.55;-webkit-font-smoothing:antialiased}
a{color:inherit;text-decoration:none}
button,input,select{font:inherit;color:inherit}
.skip{position:absolute;left:-999px;top:8px;z-index:20;background:var(--accent);color:#042018;padding:8px 14px;border-radius:8px}
.skip:focus{left:12px}
.top{height:66px;display:flex;align-items:center;justify-content:space-between;padding:0 clamp(18px,4vw,58px);border-bottom:1px solid var(--line);background:rgba(8,13,18,.86);backdrop-filter:blur(12px);position:sticky;top:0;z-index:10}
.brand{display:flex;align-items:center;gap:10px}
.mark{width:28px;height:28px;display:grid;place-items:center;border-radius:8px;background:linear-gradient(140deg,var(--accent),#2c8f9c);font-weight:800;color:#06211b}
.brand-name{font-weight:800;letter-spacing:.14em;font-size:13px}
.brand-tag{color:var(--dim);font-size:12px;padding-left:10px;border-left:1px solid var(--line)}
.top-meta{color:var(--dim);font-size:12px;display:flex;align-items:center;gap:8px}
.live-dot{width:7px;height:7px;border-radius:50%;background:var(--accent);box-shadow:0 0 0 4px rgba(94,231,183,.12)}
.shell{max-width:1280px;margin:0 auto;padding:0 clamp(18px,4vw,42px) 60px}
.hero{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(300px,.65fr);gap:36px;align-items:end;padding:56px 0 34px}
.eyebrow{display:inline-block;font-size:11px;font-weight:700;letter-spacing:.18em;color:var(--accent);text-transform:uppercase}
h1{font-size:clamp(34px,5vw,64px);line-height:1.02;letter-spacing:-.04em;margin:14px 0 18px;font-weight:750}
h1 em{font-style:normal;color:var(--accent)}
.hero-copy p{max-width:660px;color:var(--dim);font-size:15px;margin:0 0 20px}
.formula-inline{display:inline-flex;padding:9px 14px;border:1px solid var(--line);border-radius:9px;background:var(--panel);color:#bcd2e2;font-size:12px;font-variant-numeric:tabular-nums}
.kpis{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.kpi{background:linear-gradient(160deg,var(--panel2),var(--panel));border:1px solid var(--line);border-radius:var(--radius);padding:18px 18px 16px}
.kpi span{display:block;color:var(--dim);font-size:11px;text-transform:uppercase;letter-spacing:.1em}
.kpi b{display:block;font-size:34px;line-height:1.2;margin-top:6px;font-variant-numeric:tabular-nums;letter-spacing:-.03em}
.kpi small{font-size:15px;color:var(--dim);font-weight:500}
.controls{display:grid;grid-template-columns:2fr 1.25fr 1.25fr 1.25fr auto;gap:12px;align-items:end;padding:18px;background:var(--panel);border:1px solid var(--line);border-radius:var(--radius)}
.field label{display:block;font-size:10px;text-transform:uppercase;letter-spacing:.13em;color:var(--dim);margin-bottom:7px}
.field input,.field select{width:100%;height:40px;border-radius:9px;border:1px solid #2b3d4d;background:#0a1219;padding:0 12px;outline:0}
.field input:focus,.field select:focus{border-color:var(--accent);box-shadow:0 0 0 3px rgba(94,231,183,.12)}
.clear,.button{height:40px;padding:0 16px;border-radius:9px;border:1px solid #2b3d4d;background:transparent;cursor:pointer;color:var(--dim)}
.clear:hover,.button:hover{border-color:var(--accent);color:var(--accent)}
.count{color:var(--dim);font-size:12px;margin:16px 2px 10px}
.panel{background:var(--panel);border:1px solid var(--line);border-radius:var(--radius);overflow:hidden}
.tablewrap{overflow-x:auto}
table{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums}
th{text-align:left;font-size:10px;text-transform:uppercase;letter-spacing:.12em;color:var(--dim);font-weight:700;background:#101923;border-bottom:1px solid var(--line);white-space:nowrap}
th:first-child,td:first-child{padding-left:18px}
th:last-child,td:last-child{padding-right:16px}
.sort{border:0;background:transparent;padding:12px 10px;color:inherit;text-transform:inherit;letter-spacing:inherit;font-weight:inherit;cursor:pointer}
.sort:hover{color:var(--accent)}
.arrow{color:var(--accent);margin-left:4px}
td{padding:12px 10px;border-bottom:1px solid #182633;vertical-align:middle}
tbody tr:last-child td{border-bottom:0}
tbody tr:hover{background:#14202b}
.rank{color:var(--dim);width:48px;font-weight:600}
.pname{font-weight:650;letter-spacing:-.01em}
.pmeta{color:var(--dim);font-size:11px;margin-top:2px}
.num{text-align:right;white-space:nowrap}
.pos{color:var(--accent)!important}.neg{color:var(--neg)!important}
.barwrap{display:flex;align-items:center;gap:8px;min-width:130px}
.bar{height:5px;flex:1;border-radius:4px;background:#1d2b38;overflow:hidden}
.bar i{display:block;height:100%;border-radius:4px;background:linear-gradient(90deg,#2f9f94,var(--accent))}
.barwrap span{color:var(--dim);font-size:11px;width:42px;text-align:right}
.conf{display:inline-block;padding:3px 9px;border-radius:20px;font-size:10px;font-weight:700;letter-spacing:.05em;text-transform:uppercase}
.conf.high{background:rgba(94,231,183,.14);color:var(--accent)}
.conf.medium{background:rgba(127,183,255,.14);color:var(--accent2)}
.conf.low{background:rgba(255,184,107,.14);color:var(--warn)}
.go{text-align:right}
.go a{display:inline-grid;place-items:center;width:28px;height:28px;border-radius:8px;border:1px solid var(--line);color:var(--accent)}
.go a:hover{background:var(--accent);color:#06211b}
.empty{padding:40px;text-align:center}.empty h3{margin:0 0 6px}.empty p{color:var(--dim)}
.screened{margin-top:32px}
.screened h2,.method h2{font-size:18px;letter-spacing:-.02em;margin:0 0 4px}
.screened h2 span{color:var(--warn);font-size:13px}
.screened>p,.method p{color:var(--dim);margin:0 0 14px}
.screen-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:10px}
.screen-grid article{padding:14px 16px;border:1px solid var(--line);border-radius:11px;background:var(--panel)}
.screen-grid article div{display:flex;justify-content:space-between;gap:8px}
.screen-grid article span{color:var(--dim);font-size:11px}
.screen-grid article p{color:var(--dim);font-size:12px;margin:8px 0 0}
.method{margin-top:32px;padding:22px;border:1px solid var(--line);border-radius:var(--radius);background:linear-gradient(130deg,var(--panel2),var(--panel));display:grid;grid-template-columns:1.4fr 1fr;gap:28px}
.compchips{display:flex;flex-wrap:wrap;gap:7px;align-content:start}
.compchips span{padding:6px 10px;border:1px solid var(--line);border-radius:20px;background:#0a1219;font-size:11px;color:var(--accent2)}
.compchips b{color:var(--ink);font-weight:600}
.compchips small{color:var(--dim)}
footer{color:#667e91;font-size:11px;margin-top:30px;border-top:1px solid var(--line);padding-top:16px}
.back{display:inline-block;color:var(--dim);font-size:12px;margin:26px 0 18px}
.back:hover{color:var(--accent)}
.detail-head{display:flex;justify-content:space-between;align-items:end;gap:24px;margin-bottom:24px}
.detail-head h1{font-size:clamp(30px,4vw,50px);margin:10px 0 12px}
.chips{display:flex;flex-wrap:wrap;gap:6px}
.chips span{padding:4px 10px;border-radius:20px;border:1px solid var(--line);background:var(--panel);color:var(--dim);font-size:11px}
.headvalue{text-align:right;flex-shrink:0}
.headvalue span{display:block;color:var(--dim);font-size:11px;text-transform:uppercase;letter-spacing:.12em}
.headvalue b{font-size:clamp(28px,4vw,44px);color:var(--accent);letter-spacing:-.04em;font-variant-numeric:tabular-nums}
.detail-grid{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(260px,.75fr);gap:16px;align-items:start}
.maincol,.side{display:flex;flex-direction:column;gap:16px}
.card{padding:22px;border:1px solid var(--line);border-radius:var(--radius);background:var(--panel)}
.card h2{font-size:13px;text-transform:uppercase;letter-spacing:.12em;color:var(--dim);margin:0 0 16px}
.card h2 span{text-transform:none;letter-spacing:0;color:var(--accent);font-size:11px;margin-left:8px}
.thesis{font-size:16px;line-height:1.7;margin:0;color:#dce9f2}
.compare{display:flex;flex-direction:column;gap:15px}
.clabel{display:flex;justify-content:space-between;font-size:12px;margin-bottom:6px}
.clabel b{font-variant-numeric:tabular-nums}
.ctrack{height:11px;border-radius:7px;background:#1a2835;overflow:hidden}
.ctrack i{display:block;height:100%;border-radius:7px}
.c0{background:linear-gradient(90deg,#2f9f94,var(--accent))}.c1{background:var(--accent2)}.c2{background:#627c90}
.crow small{display:block;color:var(--dim);font-size:10px;margin-top:4px}
.note{color:var(--dim);font-size:12px;margin:14px 0 0}
.steps{list-style:none;margin:0;padding:0;counter-reset:s}
.steps li{display:flex;gap:14px;padding:12px 0;border-top:1px solid #192734}
.steps li:first-child{border-top:0}
.stepno{flex-shrink:0;width:26px;height:26px;display:grid;place-items:center;border-radius:8px;background:#152732;color:var(--accent);font-size:10px;font-weight:800}
.steps p{margin:2px 0 0;color:#c6d6e3;font-size:13px}
.stats dl{margin:0}
.stats dl div{display:flex;justify-content:space-between;gap:12px;padding:10px 0;border-bottom:1px solid #192734}
.stats dl div:last-child{border-bottom:0}
.stats dt{color:var(--dim);font-size:12px}
.stats dd{margin:0;font-weight:650;text-align:right;font-variant-numeric:tabular-nums}
.error{padding:40px;color:var(--warn)}
@media(max-width:980px){.hero{grid-template-columns:1fr;padding-top:36px}.kpis{grid-template-columns:repeat(4,1fr)}.controls{grid-template-columns:1fr 1fr}.detail-grid{grid-template-columns:1fr}.method{grid-template-columns:1fr}}
@media(max-width:640px){.top{padding:0 16px}.brand-tag{display:none}.kpis{grid-template-columns:1fr 1fr}.controls{grid-template-columns:1fr}.detail-head{display:block}.headvalue{text-align:left;margin-top:16px}.card{padding:16px}}
```

